async function runInOrder<Input, Intermediate, Output>(
  input: Input,
  agentA: Agent<Input, Intermediate>,
  agentB: Agent<Intermediate, Output>,
): Promise<Output> {
  const resultA = await agentA(input);
  return agentB(resultA);
}
